# Reference values for epistat_linalg::basis::{harrell_knots, RestrictedCubic,
# natural_spline_knots, NaturalSpline}: Hmisc::rcspline.eval and splines::ns.
# The samples are generated by the integer rule below, which the Rust test
# repeats, so only knots and bases are stored.
# Run: PATH=/opt/homebrew/opt/r/bin:$PATH Rscript splines_rcs.R > splines_rcs.json
suppressMessages({
  library(Hmisc)
  library(splines)
  library(jsonlite)
})

# n distinct values in [0, 100), a fraction tie_low of them replaced by 0 and
# a fraction tie_high by 100, taken from the front and the back.
sample_x <- function(n, tie_low = 0, tie_high = 0) {
  i <- seq_len(n)
  x <- ((i * 7919) %% 10007) / 10007 * 100
  if (tie_low > 0) x[seq_len(floor(tie_low * n))] <- 0
  if (tie_high > 0) x[(n - floor(tie_high * n) + 1):n] <- 100
  x
}

# Hmisc rcspline.eval
rcs <- list()
for (k in 3:7) {
  knots <- seq(5, 80, length.out = k) + c(0, 1.3, -0.7, 2.1, 0, 0.9, 0)[seq_len(k)]
  knots <- sort(knots)
  x <- c(seq(-10, 110, length.out = 61), knots, 250)
  for (norm in 0:2) {
    for (inclx in c(FALSE, TRUE)) {
      b <- rcspline.eval(x, knots = knots, norm = norm, inclx = inclx)
      attr(b, "knots") <- NULL
      rcs[[length(rcs) + 1]] <- list(knots = knots, norm = norm, inclx = inclx,
                                     x = x, basis = unname(b))
    }
  }
}

# Hmisc knots
kn <- list()
for (n in c(30, 99, 100, 2000)) {
  for (nk in 3:7) {
    for (ties in list(c(0, 0), c(0.05, 0), c(0.10, 0), c(0.30, 0), c(0, 0.10), c(0.10, 0.30))) {
      x <- sample_x(n, ties[1], ties[2])
      res <- tryCatch(suppressWarnings(rcspline.eval(x, nk = nk, knots.only = TRUE)),
                      error = function(e) NULL)
      kn[[length(kn) + 1]] <- list(n = n, nk = nk, tie_low = ties[1], tie_high = ties[2],
                                   knots = if (is.null(res)) NULL else unname(res))
    }
  }
}

# splines::ns
nsl <- list()
x <- sample_x(500)
x <- c(x, x[1:20])
xnew <- c(seq(-20, 120, length.out = 71), 0, 100, x[1:5])
d1 <- function(f, x, h = 1e-3) {
  (-f(x + 2 * h) + 8 * f(x + h) - 8 * f(x - h) + f(x - 2 * h)) / (12 * h)
}
add_ns <- function(x, df, intercept, boundary = NULL, tie = 0) {
  b <- if (is.null(boundary)) suppressWarnings(ns(x, df = df, intercept = intercept))
       else suppressWarnings(ns(x, df = df, intercept = intercept, Boundary.knots = boundary))
  pred <- function(z) unclass(predict(b, z))[, , drop = FALSE]
  basis <- pred(xnew)
  deriv <- sapply(seq_len(ncol(basis)), function(j) d1(function(z) pred(z)[, j], xnew))
  nsl[[length(nsl) + 1]] <<- list(
    n = length(x), tie_low = tie, df = df, intercept = intercept,
    boundary = I(as.vector(attr(b, "Boundary.knots"))), knots = I(as.vector(attr(b, "knots"))),
    given_boundary = !is.null(boundary), xnew = xnew,
    basis = unname(basis), deriv = unname(matrix(deriv, nrow(basis))),
    fitted = unname(unclass(b)[1:5, , drop = FALSE]))
}
for (df in 1:6) for (int in c(FALSE, TRUE)) add_ns(x, df, int)
for (df in 2:5) add_ns(x, df, FALSE, boundary = c(10, 90))
# A point mass at the lower boundary moves an interior knot inward.
xt <- sample_x(400, 0.4)
for (df in 3:5) {
  b <- suppressWarnings(ns(xt, df = df))
  basis <- unclass(predict(b, xnew))
  nsl[[length(nsl) + 1]] <- list(
    n = 400, tie_low = 0.4, df = df, intercept = FALSE, given_boundary = FALSE,
    boundary = I(as.vector(attr(b, "Boundary.knots"))), knots = I(as.vector(attr(b, "knots"))),
    xnew = xnew, basis = unname(basis),
    deriv = unname(sapply(seq_len(ncol(basis)), function(j)
      d1(function(z) unclass(predict(b, z))[, j], xnew))),
    fitted = unname(unclass(b)[1:5, , drop = FALSE]))
}

cat(toJSON(list(r = R.version.string, hmisc = as.character(packageVersion("Hmisc")),
                rms = tryCatch(as.character(packageVersion("rms")), error = function(e) NA),
                splines = as.character(packageVersion("splines")),
                rcs = rcs, knots = kn, ns = nsl),
           digits = NA, auto_unbox = TRUE, null = "null", na = "null"))
